<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller;
use App\Http\Responses\ApiResponse;
use App\Models\ResearchProject;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
class ResearchProjectController extends Controller { public function index(Request $request): JsonResponse { $projects=ResearchProject::with(['course:id,code,name_ar,name_en','department:id,name_ar,name_en'])->when(!$request->boolean('show_archived'), fn($q) => $q->whereNull('archived_at'))->when($request->query('academic_year'),fn($query,$year)=>$query->where('academic_year',$year))->orderByDesc('academic_year')->orderBy('title')->paginate($request->integer('per_page',50)); return ApiResponse::success($projects->items(),null,['total'=>$projects->total()]); } public function store(Request $r):JsonResponse{$d=$r->validate(['title'=>['required','string','max:500'],'academic_year'=>['nullable','string'],'course_id'=>['nullable','exists:courses,id'],'department_id'=>['nullable','exists:departments,id'],'supervisor'=>['nullable','string'],'student_identifiers'=>['nullable','string'],'ethical_approval_status'=>['nullable','string'],'project_stage'=>['nullable','string'],'submission_date'=>['nullable','date'],'score'=>['nullable','numeric'],'publication_status'=>['nullable','string'],'notes'=>['nullable','string']]);return ApiResponse::success(ResearchProject::create($d),'Research project created.',[],201);} public function update(Request $r,ResearchProject $researchProject):JsonResponse{$researchProject->update($r->validate(['title'=>['sometimes','string','max:500'],'project_stage'=>['nullable','string'],'ethical_approval_status'=>['nullable','string'],'score'=>['nullable','numeric'],'publication_status'=>['nullable','string'],'notes'=>['nullable','string']]));return ApiResponse::success($researchProject->fresh());} public function archive(ResearchProject $researchProject):JsonResponse{$researchProject->update(['archived_at'=>now()]);return ApiResponse::success($researchProject->fresh(),'Record archived.');} }
